/** A script-level failure. Stops the script unless caught by try/except. */
export class Failure extends Error {
    statusCode;
    reason;
    command = '';
    line = 0;
    located = false;
    constructor(statusCode, reason) {
        super(reason);
        this.name = 'Failure';
        this.statusCode = statusCode;
        this.reason = reason;
    }
    locate(line, command) {
        if (!this.located) {
            this.line = line;
            this.command = command;
            this.located = true;
        }
        return this;
    }
    payload() {
        return {
            status: 'failure',
            reason: this.reason,
            command: this.command,
            line: this.line,
            status_code: this.statusCode,
        };
    }
}
/** Thrown by `success`: stops the script with a result. */
export class SuccessSignal {
    value;
    constructor(value) {
        this.value = value;
    }
}
/** Strict syntax error found while parsing; never catchable by scripts. */
export class SplSyntaxError extends Error {
    line;
    col;
    constructor(message, line, col) {
        super(message);
        this.line = line;
        this.col = col;
        this.name = 'SplSyntaxError';
    }
    format(file) {
        return `${file}:${this.line}:${this.col}: syntax error: ${this.message}`;
    }
}
